constexpr double tau=6.283185307179586;
void require(bool v,const char* text){if(!v){std::cerr<<text<<'\n';std::exit(1);}}
double rms(const std::vector<float>& a){double e=0;for(auto v:a)e+=v*v;return std::sqrt(e/a.size());}
double delta(const std::vector<float>& a,const std::vector<float>& b){double e=0;for(std::size_t i=0;i<a.size();++i)e+=(a[i]-b[i])*(a[i]-b[i]);return std::sqrt(e/a.size())/std::max(1e-12,rms(a));}
std::vector<float> input(int kind,int sr,int count){std::vector<float> a(count);for(int i=0;i<count;++i){double t=double(i)/sr,p=std::fmod(t*55,1.),s=std::sin(t*tau*55),v=0;switch(kind){case 0:v=.45*s;break;case 1:v=.26*(2*p-1);break;case 2:v=.26*(p<.5?1:-1);break;case 3:v=(.32*s+.12*std::sin(t*tau*220)+.08*std::sin(t*tau*715))*std::max(0.,1-std::fmod(t,.25)/.12);break;case 4:v=.36*s+.08*std::sin(t*tau*110)+.025*std::sin(t*tau*330);break;default:break;}a[i]=float(v);}return a;}
std::vector<float> render(const std::vector<float>& a,float x,float y,const DnaProfile* dna=nullptr,float mutate=1,float drive=0,int sr=48000){CrushDSP dsp;dsp.prepare(sr);auto m=XYMapping::map(x,y,sr);CrushDSP::Parameters p;p.bits=m.bits;p.rate=m.rate;p.activity=m.activity;p.centered=true;p.drive=drive;p.mutate=mutate;p.mix=1;p.output=0;std::vector<float>b;for(auto v:a){float f[]{v,v};dsp.processFrame(f,2,p,dna);require(std::isfinite(f[0])&&std::abs(f[0])<1.0001f,"Unstable centred output/peak");b.push_back(f[0]);}return b;}
DnaProfile profile(int kind){const int sr=48000;std::vector<float>a(sr/2);unsigned state=42;for(int i=0;i<int(a.size());++i){double t=double(i)/sr;state=state*1664525+1013904223;double noise=(double(state>>8)/16777216-.5);a[i]=float(kind==0?(std::sin(t*tau*1270)+.8*std::sin(t*tau*2317))*std::exp(-t*9)*.35:kind==1?(.4*std::sin(t*tau*450)+.3*std::sin(t*tau*1400)+.2*std::sin(t*tau*2600))*(.65+.35*std::sin(t*tau*4)):noise*.8*std::exp(-std::fmod(t,.12)*60));}const float* channels[]{a.data()};return DnaProfile::analyse(channels,1,a.size(),sr);}
void write(const std::filesystem::path& f,const std::vector<float>& a){std::ofstream out(f,std::ios::binary);auto word=[&](unsigned v,int n){for(int i=0;i<n;++i)out.put(char((v>>(i*8))&255));};out.write("RIFF",4);word(36+unsigned(a.size()*2),4);out.write("WAVEfmt ",8);word(16,4);word(1,2);word(1,2);word(48000,4);word(96000,4);word(2,2);word(16,2);out.write("data",4);word(unsigned(a.size()*2),4);for(auto v:a){require(std::abs(v)<=1,"Audition WAV would clip");word(unsigned(int(v*32767)),2);}}
