 for(double sr:{44100.,48000.,96000.,192000.}){auto center=XYMapping::map(0,0,sr);require(center.bits==16&&center.rate==sr&&center.activity==0,"Centre not neutral");float bits=16,rate=float(sr);for(float d:{.0001f,.001f,.01f,.05f,.1f,.25f,.5f,.75f,1.f}){auto x=XYMapping::map(d,0,sr),y=XYMapping::map(0,d,sr),nx=XYMapping::map(-d,0,sr),ny=XYMapping::map(0,-d,sr);require(x.bits<bits&&y.rate<rate,"Axis progression has a dead zone or reversal");require(x.rate==sr&&y.bits==16,"Axes lost separate roles");require(x.bits==nx.bits&&y.rate==ny.rate,"Opposite directions are inconsistent");bits=x.bits;rate=y.rate;}}
 auto metal=profile(0),vocal=profile(1),noise=profile(2);double peak=0;
