 auto a=input(3,48000,48000);auto base=render(a,.6f,-.5f),m=render(a,.6f,-.5f,&metal),v=render(a,.6f,-.5f,&vocal),n=render(a,.6f,-.5f,&noise);require(render(a,.6f,-.5f,&metal,0)==render(a,.6f,-.5f,&noise,0),"MUTATE0 donor leakage");require(render(a,.6f,-.5f,&metal,0)==render(a,.6f,-.5f,nullptr,0),"MUTATE0 differs from no sample");auto matched=[](std::vector<float> x){float g=float(.12/std::max(1e-12,rms(x)));for(auto&v:x)v*=g;return x;};double dnaDifference=std::min({delta(matched(m),matched(v)),delta(matched(m),matched(n)),delta(matched(v),matched(n))});std::cout<<"DNA0-drive minimum loudness-matched profile difference "<<dnaDifference<<" maximum test peak "<<peak<<'\n';require(dnaDifference>.08,"DNA profile is inaudible at DRIVE0");
 // All pre-update processing must remain bit-for-bit identical.
