 // Fast XY motion and rate changes stay finite, with a continuous centre return.
 for(int sr:{44100,96000,192000}){CrushDSP dsp;dsp.prepare(sr);CrushDSP::Parameters p;p.centered=true;p.drive=0;p.output=0;p.mix=1;float previous=0,maxStep=0;for(int i=0;i<sr;++i){float angle=float(tau*i/sr),radius=.95f*std::abs(std::sin(angle));auto map=XYMapping::map(radius*std::cos(angle),radius*std::sin(angle),sr);p.bits=map.bits;p.rate=map.rate;p.activity=map.activity;float frame[]{.4f*std::sin(float(tau*55*i/sr))};dsp.processFrame(frame,1,p,&metal);require(std::isfinite(frame[0])&&std::abs(frame[0])<1.5,"XY sweep unstable");maxStep=std::max(maxStep,std::abs(frame[0]-previous));previous=frame[0];}std::cout<<"sweep "<<sr<<" max step "<<maxStep<<'\n';require(maxStep<.4,"Parameter sweep discontinuity");}
 for(float drive:{0.f,18.f,36.f}){double maxPeak=0;for(int kind=0;kind<5;++kind){auto loud=input(kind,48000,24000);float pk=0;for(float z:loud)pk=std::max(pk,std::abs(z));for(float&z:loud)z*=.9f/pk;for(auto xy:std::vector<std::array<float,2>>{{1,0},{0,1},{.707f,.707f}})for(auto dna:{&metal,&vocal,&noise}){auto out=render(loud,xy[0],xy[1],dna,1,drive);for(float z:out)maxPeak=std::max(maxPeak,double(std::abs(z)));}}std::cout<<"loud input0.9 peak DRIVE "<<drive<<" = "<<maxPeak<<'\n';require(maxPeak<1,"Full-level drive stress exceeded unity");}
 // Distinguish harmonic change from a simple gain change on a sustained sine.
 auto sine=input(0,48000,96000);auto crunch=render(sine,1,0);auto magnitude=[](const std::vector<float>& a,double hz){double re=0,im=0;for(std::size_t i=48000;i<a.size();++i){re+=a[i]*std::cos(tau*hz*i/48000);im+=a[i]*std::sin(tau*hz*i/48000);}return 2*std::hypot(re,im)/(a.size()-48000);};
 double harmonics=0;for(int h=2;h<=24;++h)harmonics+=std::pow(magnitude(crunch,55*h),2);double harmonicRatio=std::sqrt(harmonics)/magnitude(crunch,55);std::cout<<"Horizontal extreme harmonic/fundamental ratio "<<harmonicRatio<<'\n';require(harmonicRatio>.05,"Crush became only gain/phase, without new harmonics");require(magnitude(crunch,55)>.03,"Bass fundamental lost");
 // Settling at neutral becomes exact, rather than leaving a tiny residual wet blend.
 {CrushDSP dsp;dsp.prepare(48000);CrushDSP::Parameters p;p.centered=true;p.mix=1;p.output=0;p.drive=0;for(int i=0;i<144000;++i){auto map=XYMapping::map(i<48000?.7f:0,i<48000?.5f:0,48000);p.bits=map.bits;p.rate=map.rate;p.activity=map.activity;const float v=.3f*std::sin(float(tau*55*i/48000));float f[]{v};dsp.processFrame(f,1,p,&metal);if(i>96000)require(f[0]==v,"Centre return never became exact dry");}}
 // Informational wall-clock comparison; noisy shared CI timing is not a DSP assertion.
 auto timing=[&](auto& effect,auto parameters){effect.prepare(48000);const auto start=std::chrono::steady_clock::now();volatile float checksum=0;for(float v:a){float f[]{v,v};effect.processFrame(f,2,parameters,&metal);checksum+=f[0];}const auto elapsed=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();require(std::isfinite(checksum),"CPU probe invalid");return elapsed;};
 CrushDSP timedNew;LegacyCrushDSP timedOld;CrushDSP::Parameters modern;LegacyCrushDSP::Parameters legacy;const auto bm=XYMapping::map(.6f,-.5f,48000);modern.bits=legacy.bits=bm.bits;modern.rate=legacy.rate=bm.rate;modern.drive=legacy.drive=18;modern.mutate=legacy.mutate=1;modern.centered=true;modern.activity=bm.activity;std::array<double,3> newer{},older{};for(int i=0;i<3;++i){newer[i]=timing(timedNew,modern);older[i]=timing(timedOld,legacy);}std::sort(newer.begin(),newer.end());std::sort(older.begin(),older.end());std::cout<<"CPU stereo 1sec audio median legacy "<<older[1]<<"ms centred "<<newer[1]<<"ms ratio "<<newer[1]/older[1]<<'\n';
 if(argc>1){auto dir=std::filesystem::path(argv[1]);std::filesystem::create_directories(dir);std::ofstream report(dir/"XY-validation.txt");report<<"Automated synthetic tests only; subjective listening and FL Studio verification remain manual.\nLegacy processing: bit-for-bit identical. Centre: exact unity dry including DRIVE36/DNA100.\nSine horizontal harmonic/fundamental ratio: "<<harmonicRatio<<"\nMinimum loudness-matched DNA waveform difference at DRIVE0: "<<dnaDifference<<"\nStereo 1sec CPU median: legacy "<<older[1]<<" ms, centred "<<newer[1]<<" ms.\nCPU timings are machine/load dependent, not a DAW benchmark.\n";auto bass=input(3,48000,96000);write(dir/"xy-centre-dry-synthetic-stabs.wav",bass);write(dir/"xy-horizontal-crunch-drive0.wav",render(bass,.85f,0));write(dir/"xy-vertical-rate-drive0.wav",render(bass,0,.85f));write(dir/"xy-combined-drive0.wav",render(bass,.6f,-.65f));write(dir/"xy-combined-drive0-matched.wav",matched(render(bass,.6f,-.65f)));write(dir/"xy-combined-drive36-matched.wav",matched(render(bass,.6f,-.65f,nullptr,1,36)));write(dir/"xy-dna-metallic-drive0-matched.wav",matched(render(bass,.6f,-.65f,&metal)));write(dir/"xy-dna-vowel-drive0-matched.wav",matched(render(bass,.6f,-.65f,&vocal)));write(dir/"xy-dna-percussion-drive0-matched.wav",matched(render(bass,.6f,-.65f,&noise)));}
